import java.io.IOException;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.ExecutionException;

/** Console entry point. Uses fictional training data, not live railway systems. */
public class Main {
    private static final Scanner IN=new Scanner(System.in); private static final RailwayStore STORE=new RailwayStore(); private static final Random RNG=new Random();
    public static void main(String[]args){banner();boolean go=true;while(go){menu();switch(integer("Select option: ")){case 1->trainMenu();case 2->scheduleMenu();case 3->ticketMenu();case 4->routeFlow();case 5->incidentMenu();case 6->eventMonitor();case 7->reports();case 8->algorithmLab();case 9->save();case 0->{save();go=false;System.out.println("RailSync closed. Have a safe journey!");}default->System.out.println("Invalid option. Please choose from the menu.");}}}
    private static void banner(){System.out.println("\n╔══════════════════════════════════════════════════════════╗");System.out.println("║                         R A I L S Y N C                  ║");System.out.println("║            INTELLIGENT RAILWAY OPERATIONS                ║");System.out.println("╚══════════════════════════════════════════════════════════╝");System.out.println(" DEMO MODE · Java console · CSV persistence · DSA decision support");}
    private static void menu(){System.out.println("\n-------------------- OPERATIONS MENU ----------------------");System.out.println(" 1. Train & station service records");System.out.println(" 2. Timetable & platform allocation");System.out.println(" 3. Passenger tickets & PNR search");System.out.println(" 4. Route network & passenger-flow analysis");System.out.println(" 5. Maintenance & incident reports");System.out.println(" 6. Service alerts & event monitoring");System.out.println(" 7. Operational reports & analytics");System.out.println(" 8. Advanced DSA laboratory (CO1–CO6)");System.out.println(" 9. Save all CSV data                 0. Save & exit");System.out.println("------------------------------------------------------------");}
    private static String ask(String p){System.out.print(p);return IN.nextLine().trim();}private static int integer(String p){try{return Integer.parseInt(ask(p));}catch(NumberFormatException e){System.out.println("Please enter a whole number.");return -999;}}private static void pause(){System.out.println("\nPress Enter to continue...");IN.nextLine();}private static String low(String s){return s.toLowerCase(Locale.ROOT);}private static void action(Runnable r){try{r.run();}catch(Exception e){System.out.println("Operation could not be completed: "+e.getMessage());}}
    private static void trainMenu(){System.out.println("\nTRAIN & SERVICE RECORDS  [1 list | 2 add | 3 update status | 4 search | 0 back]");switch(integer("Action: ")){case 1->listTrains();case 2->action(()->{String id=ask("Train ID: "),name=ask("Service name: "),from=ask("Origin station: "),to=ask("Destination station: "),status=ask("Status (ON TIME/DELAYED/CANCELLED/MAINTENANCE/ARRIVED/BOARDING): ").toUpperCase(Locale.ROOT);int passengers=integer("Current passenger count: "),capacity=integer("Capacity: ");STORE.addTrain(new RailwayStore.Train(id,name,from,to,status,passengers,capacity));System.out.println("Train added. Save to keep the change after exit.");});case 3->action(()->{STORE.updateStatus(ask("Train ID: "),ask("New status: "));System.out.println("Train status updated.");});case 4->searchRailway();case 0->{return;}default->System.out.println("Unknown action.");}}
    private static void listTrains(){System.out.printf("%-8s %-23s %-16s %-16s %-14s %10s %10s%n","ID","SERVICE","FROM","TO","STATUS","PASSENGERS","CAPACITY");for(var t:STORE.trains())System.out.printf("%-8s %-23s %-16s %-16s %-14s %10d %10d%n",t.id(),clip(t.name(),22),clip(t.from(),15),clip(t.to(),15),t.status(),t.passengers(),t.capacity());}
    private static String clip(String s,int n){return s.length()<=n?s:s.substring(0,n-1)+"…";}
    private static String searchable(){StringBuilder b=new StringBuilder();for(var t:STORE.trains())b.append(t.id()).append(" | ").append(t.name()).append(" | ").append(t.from()).append(" to ").append(t.to()).append(" | ").append(t.status()).append('\n');return b.toString();}
    private static void searchRailway(){String q=low(ask("Search train ID, station, service or status: "));String data=low(searchable());int k=Algorithms.kmp(data,q);List<Integer>rk=Algorithms.rabinKarp(data,q);System.out.println("KMP first offset: "+k+" | Rabin–Karp offsets: "+rk);int count=0;for(var t:STORE.trains())if(low(t.id()+" "+t.name()+" "+t.from()+" "+t.to()+" "+t.status()).contains(q)){System.out.println("  "+t);count++;}if(count==0)System.out.println("No train matched. Try a shorter phrase or use the spelling helper in DSA Lab.");}
    private static void scheduleMenu(){System.out.println("\nTIMETABLE & PLATFORMS [1 list | 2 add schedule | 3 conflict analysis | 0 back]");switch(integer("Action: ")){case 1->{System.out.printf("%-8s %-12s %-10s %-10s %-9s%n","TRAIN","DATE","DEPART","ARRIVE","PLATFORM");for(var s:STORE.schedules())System.out.printf("%-8s %-12s %-10s %-10s %-9s%n",s.trainId(),s.date(),s.departure(),s.arrival(),s.platform());}case 2->action(()->{String id=ask("Train ID: "),date=ask("Date (YYYY-MM-DD): "),dep=ask("Departure (HH:MM): "),arr=ask("Arrival (HH:MM): "),platform=ask("Platform: ");LocalDate.parse(date);if(!dep.matches("([01]\\d|2[0-3]):[0-5]\\d")||!arr.matches("([01]\\d|2[0-3]):[0-5]\\d"))throw new IllegalArgumentException("Use 24-hour HH:MM times");STORE.addSchedule(new RailwayStore.Schedule(id,date,dep,arr,platform));System.out.println("Schedule stored; platform/time collision check passed.");});case 3->{Map<String,Set<String>>g=new LinkedHashMap<>();List<RailwayStore.Schedule>ss=STORE.schedules();for(int i=0;i<ss.size();i++)for(int j=i+1;j<ss.size();j++){var a=ss.get(i);var b=ss.get(j);if(a.date().equals(b.date())&&a.platform().equals(b.platform())&&a.departure().equals(b.departure())){g.computeIfAbsent(a.trainId(),x->new LinkedHashSet<>()).add(b.trainId());g.computeIfAbsent(b.trainId(),x->new LinkedHashSet<>()).add(a.trainId());}}if(g.isEmpty())System.out.println("No exact same-time platform conflicts found.");else{System.out.println("Conflicting services: "+g);System.out.println("Services to review (vertex-cover 2-approx): "+Algorithms.vertexCoverApprox(g));}}case 0->{return;}default->System.out.println("Unknown action.");}}
    private static void ticketMenu(){System.out.println("\nPASSENGER & TICKETS [1 list | 2 book demo ticket | 3 PNR/passenger search | 0 back]");switch(integer("Action: ")){case 1->{for(var t:STORE.tickets())System.out.println(t.pnr()+" | "+t.passenger()+" | "+t.trainId()+" | "+t.from()+" -> "+t.to()+" | "+t.status());}case 2->action(()->{String pnr=ask("PNR: "),pass=ask("Passenger name: "),id=ask("Train ID: "),from=ask("From: "),to=ask("To: ");STORE.addTicket(new RailwayStore.Ticket(pnr,pass,id,from,to,"CONFIRMED"));System.out.println("Demo ticket created. PNR: "+pnr);});case 3->{String q=low(ask("Enter PNR, passenger or train ID: "));String joined=STORE.tickets().toString();System.out.println("KMP offset in ticket records: "+Algorithms.kmp(low(joined),q));int n=0;for(var t:STORE.tickets())if(low(t.toString()).contains(q)){System.out.println(t);n++;}if(n==0)System.out.println("No ticket found.");}case 0->{return;}default->System.out.println("Unknown action.");}}
    private static void routeFlow(){System.out.println("\nROUTE NETWORK & FLOW ANALYSIS");System.out.println("Demo nodes: 0=Vijayawada, 1=Guntur, 2=Hyderabad, 3=Chennai, 4=Bengaluru, 5=Regional hub");int[][]c={{0,12,10,0,0,0},{0,0,0,8,5,0},{0,0,0,0,7,10},{0,0,0,0,0,10},{0,0,0,0,0,8},{0,0,0,0,0,0}};System.out.println("Passenger-flow capacity, Edmonds–Karp: "+Algorithms.maxFlow(c,0,5));System.out.println("Passenger-flow capacity, Dinic:       "+Algorithms.dinicMaxFlow(c,0,5));boolean[][]eligible={{true,true,false},{true,false,true},{false,true,true}};System.out.println("Train/platform bipartite matching size: "+Algorithms.maxBipartiteMatching(eligible));System.out.println("Interpretation: a small illustrative capacity graph, not real-time operating capacity.");}
    private static void incidentMenu(){System.out.println("\nMAINTENANCE & INCIDENTS [1 list | 2 report | 3 close | 0 back]");switch(integer("Action: ")){case 1->{for(var i:STORE.incidents())System.out.println(i.id()+" | "+i.trainId()+" | "+i.category()+" | "+i.severity()+" | "+i.status()+" | "+i.description());}case 2->action(()->{String id=ask("Incident ID: "),train=ask("Train ID: "),cat=ask("Category (DELAY/MAINTENANCE/SAFETY/OTHER): ").toUpperCase(Locale.ROOT),sev=ask("Severity (LOW/MEDIUM/HIGH): ").toUpperCase(Locale.ROOT),desc=ask("Description: ");if(!Set.of("LOW","MEDIUM","HIGH").contains(sev))throw new IllegalArgumentException("Severity must be LOW, MEDIUM or HIGH");STORE.addIncident(new RailwayStore.Incident(id,train,cat,sev,desc,"OPEN"));System.out.println("Incident recorded.");});case 3->action(()->{STORE.closeIncident(ask("Incident ID to close: "));System.out.println("Incident closed.");});case 0->{return;}default->System.out.println("Unknown action.");}}
    private static void eventMonitor(){System.out.println("\nEVENT MONITOR · stored event count: "+STORE.events().size());for(String e:STORE.events())System.out.println(" • "+e);String text=low(String.join(" | ",STORE.events()));List<String>keys=List.of("delay","maintenance","alert","arrived","safety","incident");System.out.println("\nAho–Corasick alert keyword scan:");Algorithms.ahoCorasick(text,keys).forEach((k,v)->{if(!v.isEmpty())System.out.println("  "+k+" => offsets "+v);});System.out.println("Random reservoir sample (max 3 events): "+Algorithms.reservoirSample(STORE.events(),3,RNG));}
    private static void reports(){int passengers=STORE.trains().stream().mapToInt(RailwayStore.Train::passengers).sum(),capacity=STORE.trains().stream().mapToInt(RailwayStore.Train::capacity).sum();long delayed=STORE.trains().stream().filter(t->t.status().equals("DELAYED")).count(),maint=STORE.trains().stream().filter(t->t.status().equals("MAINTENANCE")).count(),open=STORE.incidents().stream().filter(i->i.status().equals("OPEN")).count();System.out.println("\n================ OPERATIONS REPORT ================");System.out.println("Train services registered : "+STORE.trains().size());System.out.println("Scheduled services        : "+STORE.schedules().size());System.out.println("Ticket records            : "+STORE.tickets().size());System.out.println("Passenger count (demo)    : "+passengers+" / capacity "+capacity);System.out.printf("Occupancy (current count) : %.1f%%%n",capacity==0?0:100.0*passengers/capacity);System.out.println("Delayed services          : "+delayed);System.out.println("Maintenance services      : "+maint);System.out.println("Open incidents            : "+open);System.out.println("Recorded events           : "+STORE.events().size());System.out.println("Data location             : data/*.csv");}
    private static void save(){try{STORE.save();System.out.println("All railway data saved to data/*.csv");}catch(IOException e){System.out.println("Save failed: "+e.getMessage());}}
    private static void algorithmLab(){System.out.println("\n================ ADVANCED DSA LAB =================");System.out.println("1 CO1 string/alert search (KMP, Z, Rabin–Karp, Aho–Corasick)");System.out.println("2 CO2 repeated pattern analysis (suffix array, LCP, suffix automaton)");System.out.println("3 CO3 planning DP (edit distance, bitmask route, matrix-chain, optimal BST)");System.out.println("4 CO4 network flow and matching (Edmonds–Karp, Dinic)");System.out.println("5 CO5 constraint SAT and reductions");System.out.println("6 CO6 randomized/parallel processing");System.out.println("0 Back");switch(integer("CO module: ")){case 1->co1();case 2->co2();case 3->co3();case 4->routeFlow();case 5->co5();case 6->co6();case 0->{return;}default->System.out.println("Unknown module.");}}
    private static void co1(){String text=low(ask("Searchable operational text (e.g. 'delay at guntur; maintenance'): "));String p=low(ask("Single phrase to locate: "));System.out.println("KMP first offset       : "+Algorithms.kmp(text,p));System.out.println("Rabin–Karp all offsets : "+Algorithms.rabinKarp(text,p));System.out.println("Z array for pattern + separator + text: "+Arrays.toString(Algorithms.zFunction(p+"$"+text)));String ks=ask("Alert keywords separated by commas: ");List<String>patterns=Arrays.stream(ks.split(",")).map(String::trim).filter(x->!x.isEmpty()).toList();System.out.println("Aho–Corasick matches: "+Algorithms.ahoCorasick(text,patterns));}
    private static void co2(){String s=ask("Enter route/event text to analyze: ");int[]sa=Algorithms.suffixArray(s),lcp=Algorithms.lcpKasai(s,sa);System.out.println("Suffix array: "+Arrays.toString(sa));System.out.println("Kasai LCP:    "+Arrays.toString(lcp));System.out.println("Distinct non-empty substrings (suffix automaton): "+Algorithms.distinctSubstringCount(s));System.out.println("Longest repeated substring length (max LCP): "+Arrays.stream(lcp).max().orElse(0));System.out.println("Implementation note: suffix array uses prefix-doubling; SA-IS induced sorting is not included in this build.");}
    private static void co3(){System.out.println("1 Station-name typo correction  2 Bitmask route  3 Matrix-chain  4 Optimal BST");switch(integer("Choice: ")){case 1->{String a=low(ask("Entered station: ")),b=low(ask("Candidate station: "));System.out.println("Levenshtein distance: "+Algorithms.levenshtein(a,b));System.out.println("Damerau–Levenshtein distance: "+Algorithms.damerauLevenshtein(a,b));}case 2->{int[][]c={{0,10,15,20},{10,0,35,25},{15,35,0,30},{20,25,30,0}};System.out.println("4-station illustrative round-trip cost: "+Algorithms.bitmaskRouteCost(c));}case 3->{int[]d={30,35,15,5,10,20,25};System.out.println("Matrix-chain minimum scalar multiplications: "+Algorithms.matrixChainCost(d));}case 4->{double[]p={0.15,0.10,0.05,0.10,0.20};System.out.printf("Optimal BST expected search cost (demo probabilities): %.3f%n",Algorithms.optimalBstCost(p));}default->System.out.println("Choose 1–4.");}}
    private static void co5(){System.out.println("SAT demo: 3 variables, clauses (x1 OR not x2), (x2 OR x3), (not x1 OR not x3)");boolean[]a=Algorithms.solveSat(3,new int[][]{{1,-2},{2,3},{-1,-3}});if(a==null)System.out.println("UNSAT");else System.out.println("SAT assignment: "+Arrays.toString(a));Algorithms.CliqueReduction reduction=Algorithms.threeSatToClique(new int[][]{{1,-2,3},{-1,2,3},{1,2,-3}});System.out.println("3-SAT → CLIQUE reduction: "+reduction.vertices().size()+" literal-occurrence vertices, "+edgeCount(reduction.edges())+" compatibility edges; target clique size = 3 clauses.");System.out.println("Reduction reminder: a k-clique in G corresponds to an independent set of size k in complement(G); vertex cover is the complement of an independent set.");Map<String,Set<String>>g=new LinkedHashMap<>();g.put("Service-A",new LinkedHashSet<>(List.of("Service-B","Service-C")));g.put("Service-B",new LinkedHashSet<>(List.of("Service-A","Service-C")));g.put("Service-C",new LinkedHashSet<>(List.of("Service-A","Service-B","Service-D")));g.put("Service-D",new LinkedHashSet<>(List.of("Service-C")));System.out.println("Conflict graph vertex-cover 2-approx: "+Algorithms.vertexCoverApprox(g));System.out.println("Brute-force SAT solver is intentionally limited to small educational instances.");}
    private static int edgeCount(boolean[][]e){int n=0;for(int i=0;i<e.length;i++)for(int j=i+1;j<e.length;j++)if(e[i][j])n++;return n;}
    private static void co6(){int[]a={4,2,7,1,6,3,8,5};System.out.println("Passenger batches: "+Arrays.toString(a));int[]sorted=a.clone();Algorithms.quickSort(sorted,0,sorted.length-1,RNG);System.out.println("Randomized QuickSort: "+Arrays.toString(sorted));System.out.println("Reservoir sample from event stream: "+Algorithms.reservoirSample(STORE.events(),Math.min(3,STORE.events().size()),RNG));long n=integer("Integer to test for primality (>=0): ");if(n>=0)System.out.println(n+" is "+(Algorithms.millerRabin(n)?"probably prime":"composite"));try{System.out.println("Sequential inclusive scan: "+Arrays.toString(Algorithms.inclusiveScan(a)));System.out.println("Parallel inclusive scan:   "+Arrays.toString(Algorithms.parallelInclusiveScan(a,3)));System.out.println("Sequential reduce: "+Algorithms.reduceSum(a));System.out.println("Parallel reduce:   "+Algorithms.parallelReduceSum(a,3));System.out.println("Brent-style upper estimate for W=1000, P=4: "+Algorithms.brentWorkEstimate(1000,4));}catch(InterruptedException e){Thread.currentThread().interrupt();System.out.println("Parallel operation interrupted.");}catch(ExecutionException e){System.out.println("Parallel operation failed: "+e.getCause());}}
}
